message.content:
{
  "answer": "A pena de morte não é aplicável em casos civis sob o disposto no inciso XLVII do Artigo 5º da CF/88, exceto em casos de guerra declarada, conforme Artigo 84, XIX. A pensão por morte é regulamentada pelo ADCT, Artigo 53, Inciso III, que estabelece pensão à viúva, companheira ou dependente, proporcional ao valor da pensão regular.",
  "abstain": false,
  "claims": [
    {
      "id": "EV007",
      "text": "de morte, salvo em caso de guerra declarada, nos termos do art. 84, XIX; | contexto: não haverá penas:",
      "evidence_ids": ["EV007"]
    },
    {
      "id": "EV008",
      "text": "em caso de morte, pensão à viúva ou companheira ou dependente, de forma proporcional, de valor igual à do inciso anterior; | contexto: Art. 53.",
      "evidence_ids": ["EV008"]
    }
  ]
}

